# myos keymap v1 — Swiss German QWERTZ (ISO)
# Motivating layout for UTM/iPad + Swiss physical keyboard.
# Keycodes are PS/2 set-1 makes (physical key positions).
# Non-ASCII letters use Latin-1 bytes via \xNN (v1 is not UTF-8).
# See docs/keymap.md

# Number row: §° 1+ 2" 3* 4ç 5% 6& 7/ 8( 9) 0= '? ^`
keycode 0x29 = \xA7 \xB0 none none
keycode 0x02 = 1 + none none
keycode 0x03 = 2 " @ none
keycode 0x04 = 3 * # none
keycode 0x05 = 4 \xE7 none none
keycode 0x06 = 5 % none none
keycode 0x07 = 6 & none none
keycode 0x08 = 7 / | none
keycode 0x09 = 8 ( none none
keycode 0x0A = 9 ) none none
keycode 0x0B = 0 = none none
keycode 0x0C = ' ? none none
keycode 0x0D = ^ ` none none
keycode 0x0E = BKSP BKSP BKSP BKSP
keycode 0x0F = TAB TAB TAB TAB

# QWERTZ letter row (y/z swapped vs US); üè [ ] on AltGr
keycode 0x10 = q Q none none
keycode 0x11 = w W none none
keycode 0x12 = e E none none
keycode 0x13 = r R none none
keycode 0x14 = t T none none
keycode 0x15 = z Z none none
keycode 0x16 = u U none none
keycode 0x17 = i I none none
keycode 0x18 = o O none none
keycode 0x19 = p P none none
keycode 0x1A = \xFC \xE8 [ none
keycode 0x1B = \xA8 ! ] none
keycode 0x1C = ENTER ENTER ENTER ENTER

# Home row: öé {  äà }  $£
keycode 0x1E = a A none none
keycode 0x1F = s S none none
keycode 0x20 = d D none none
keycode 0x21 = f F none none
keycode 0x22 = g G none none
keycode 0x23 = h H none none
keycode 0x24 = j J none none
keycode 0x25 = k K none none
keycode 0x26 = l L none none
keycode 0x27 = \xF6 \xE9 { none
keycode 0x28 = \xE4 \xE0 } none
keycode 0x2B = $ \xA3 none none

# Bottom row: ISO <>\, y where US has z, -_ on the key US labels /?
keycode 0x56 = < > \ none
keycode 0x2C = y Y none none
keycode 0x2D = x X none none
keycode 0x2E = c C none none
keycode 0x2F = v V none none
keycode 0x30 = b B none none
keycode 0x31 = n N none none
keycode 0x32 = m M none none
keycode 0x33 = , ; none none
keycode 0x34 = . : none none
keycode 0x35 = - _ none none
keycode 0x39 = SPACE SPACE SPACE SPACE
keycode 0x53 = BKSP BKSP BKSP BKSP
